function minLength(s, numOps) {
  const n = s.length;
  const runs = [];
  let length = 1;
  for (let i = 1; i <= n; i++) {
    if (i < n && s[i] === s[i - 1]) {
      length++;
    } else {
      runs.push(length);
      length = 1;
    }
  }
  const canReach = (limit) => {
    if (limit === 1) {
      let mismatches = 0;
      for (let i = 0; i < n; i++) {
        if (Number(s[i]) !== i % 2) mismatches++;
      }
      return Math.min(mismatches, n - mismatches) <= numOps;
    }
    let flips = 0;
    for (const run of runs) {
      flips += Math.floor(run / (limit + 1));
    }
    return flips <= numOps;
  };
  let left = 1;
  let right = n;
  while (left < right) {
    const mid = Math.floor((left + right) / 2);
    if (canReach(mid)) {
      right = mid;
    } else {
      left = mid + 1;
    }
  }
  return left;
}

