function minLength(s, numOps) {
  // For limit = 1, 2, ... find the fewest flips that keep every block at most limit long, by a DP over
  // (last character, length of the block it ends) along the string; return the first limit within numOps.
  const n = s.length;
  const flipsFor = (limit) => {
    let cost = [new Array(limit + 1).fill(Infinity), new Array(limit + 1).fill(Infinity)];
    for (const c of [0, 1]) cost[c][1] = Number(s[0]) === c ? 0 : 1;
    for (let i = 1; i < n; i++) {
      const next = [new Array(limit + 1).fill(Infinity), new Array(limit + 1).fill(Infinity)];
      for (const c of [0, 1]) for (let r = 1; r <= limit; r++) {
        if (cost[c][r] === Infinity) continue;
        for (const d of [0, 1]) {
          const block = d === c ? r + 1 : 1;
          if (block > limit) continue;
          const value = cost[c][r] + (Number(s[i]) === d ? 0 : 1);
          if (value < next[d][block]) next[d][block] = value;
        }
      }
      cost = next;
    }
    return Math.min(...cost[0], ...cost[1]);
  };
  for (let limit = 1; ; limit++) if (flipsFor(limit) <= numOps) return limit;
}

