function generate(rand, size) {
  const n = size === 'large' ? 1000 : 1 + Math.floor(rand() * 12);
  // Build the string from runs of random lengths so that long blocks of equal characters are common.
  const longest = 1 + Math.floor(rand() * (size === 'large' ? 120 : 8));
  let s = '';
  let bit = rand() < 0.5 ? '0' : '1';
  while (s.length < n) {
    s += bit.repeat(1 + Math.floor(rand() * longest));
    bit = bit === '0' ? '1' : '0';
  }
  s = s.slice(0, n);
  // Mostly few operations, so that the answer is not always 1.
  const share = rand();
  const numOps = Math.min(n, Math.floor(share * share * (size === 'large' ? share : 1) * (n + 1)));
  return [s, numOps];
}
